values ('bbbb0005-0000-4000-8000-000000000004', 'en', null, 'French & Francophone Culture', 'A guided tour of France and the wider French-speaking world: its history, language, literature, art, cinema, food, fashion, and civic values. Topic selection and structure adapted from Wikipedia, the free encyclopedia (article ''Culture of France'', CC BY-SA 4.0). All prose here is original.', null, 'foundations', 44, true, 'humanities', '{}')
